import uuid
from datetime import datetime,timezone
from decimal import Decimal
from sqlalchemy import String,Text,Boolean,Integer,Numeric,DateTime,ForeignKey,JSON,Index
from sqlalchemy.orm import Mapped,mapped_column,relationship
from app.db.base import Base
def now(): return datetime.now(timezone.utc)
class User(Base):
 __tablename__='users'; id:Mapped[uuid.UUID]=mapped_column(primary_key=True,default=uuid.uuid4); email:Mapped[str]=mapped_column(String(320),unique=True,index=True); password_hash:Mapped[str]=mapped_column(String(255)); is_active:Mapped[bool]=mapped_column(Boolean,default=True); created_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=now)
class UserProfile(Base):
 __tablename__='user_profiles'; id:Mapped[uuid.UUID]=mapped_column(primary_key=True,default=uuid.uuid4); user_id:Mapped[uuid.UUID]=mapped_column(ForeignKey('users.id',ondelete='CASCADE'),unique=True); preferred_language:Mapped[str]=mapped_column(String(20),default='en'); dietary_preferences:Mapped[list]=mapped_column(JSON,default=list); allergies:Mapped[list]=mapped_column(JSON,default=list); disliked_foods:Mapped[list]=mapped_column(JSON,default=list); budget_preference:Mapped[str|None]=mapped_column(String(30)); max_cooking_time:Mapped[int|None]=mapped_column(Integer)
class RefreshToken(Base):
 __tablename__='refresh_tokens'; id:Mapped[uuid.UUID]=mapped_column(primary_key=True,default=uuid.uuid4); user_id:Mapped[uuid.UUID]=mapped_column(ForeignKey('users.id',ondelete='CASCADE'),index=True); token_hash:Mapped[str]=mapped_column(String(64),unique=True); revoked:Mapped[bool]=mapped_column(Boolean,default=False); expires_at:Mapped[datetime]=mapped_column(DateTime(timezone=True))
class CravingSession(Base):
 __tablename__='craving_sessions'; __table_args__=(Index('ix_craving_user_created','user_id','created_at'),)
 id:Mapped[uuid.UUID]=mapped_column(primary_key=True,default=uuid.uuid4); user_id:Mapped[uuid.UUID]=mapped_column(ForeignKey('users.id',ondelete='CASCADE')); craving_text:Mapped[str]=mapped_column(Text); normalized_food:Mapped[str]=mapped_column(String(150)); category:Mapped[str]=mapped_column(String(100),index=True); cuisine:Mapped[str|None]=mapped_column(String(100)); flavor_profile:Mapped[list]=mapped_column(JSON,default=list); texture_profile:Mapped[list]=mapped_column(JSON,default=list); estimated_junk_cost:Mapped[Decimal]=mapped_column(Numeric(10,2),default=0); craving_intensity:Mapped[int|None]=mapped_column(Integer); weather_context:Mapped[dict]=mapped_column(JSON,default=dict); ai_analysis:Mapped[dict]=mapped_column(JSON,default=dict); status:Mapped[str]=mapped_column(String(20),default='ACTIVE'); created_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=now); updated_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=now,onupdate=now); suggestions=relationship('CravingSuggestion',cascade='all, delete-orphan'); outcome=relationship('CravingOutcome',uselist=False,cascade='all, delete-orphan')
class CravingSuggestion(Base):
 __tablename__='craving_suggestions'; id:Mapped[uuid.UUID]=mapped_column(primary_key=True,default=uuid.uuid4); craving_session_id:Mapped[uuid.UUID]=mapped_column(ForeignKey('craving_sessions.id',ondelete='CASCADE')); level:Mapped[int]=mapped_column(Integer); title:Mapped[str]=mapped_column(String(200)); description:Mapped[str]=mapped_column(Text); estimated_cost:Mapped[Decimal]=mapped_column(Numeric(10,2)); estimated_time_minutes:Mapped[int]=mapped_column(Integer); ingredients:Mapped[list]=mapped_column(JSON,default=list); instructions:Mapped[list]=mapped_column(JSON,default=list); health_benefit:Mapped[str]=mapped_column(Text,default=''); craving_match_reason:Mapped[str]=mapped_column(Text,default=''); source_type:Mapped[str]=mapped_column(String(30),default='AI')
class CravingOutcome(Base):
 __tablename__='craving_outcomes'; id:Mapped[uuid.UUID]=mapped_column(primary_key=True,default=uuid.uuid4); craving_session_id:Mapped[uuid.UUID]=mapped_column(ForeignKey('craving_sessions.id',ondelete='CASCADE'),unique=True); outcome_type:Mapped[str]=mapped_column(String(30)); selected_suggestion_id:Mapped[uuid.UUID|None]=mapped_column(ForeignKey('craving_suggestions.id',ondelete='SET NULL')); actual_food:Mapped[str|None]=mapped_column(String(200)); actual_cost:Mapped[Decimal]=mapped_column(Numeric(10,2),default=0); estimated_original_cost:Mapped[Decimal]=mapped_column(Numeric(10,2),default=0); money_saved:Mapped[Decimal]=mapped_column(Numeric(10,2),default=0); notes:Mapped[str|None]=mapped_column(Text); created_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),default=now)
